// ⚠ INTENTIONALLY BROKEN — demonstrates the IllegalStateException
package com.bank.report.service;

import com.bank.report.model.Trade;
import com.bank.report.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.Comparator;
import java.util.stream.Stream;

@Service
@RequiredArgsConstructor
@Slf4j
public class BrokenReportService {

    private final TradeRepository tradeRepo;

    @Transactional(readOnly = true)
    public String demonstrateCrash() {
        // Create ONE stream:
        Stream<Trade> settled = tradeRepo.findAll().stream()
            .filter(Trade::isSettled);

        // Terminal #1 — works fine:
        long count = settled.count();
        log.info("Count: {}", count);

        // Terminal #2 — CRASHES!
        try {
            BigDecimal total = settled
                .map(Trade::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
            return "This line never executes";
        } catch (IllegalStateException e) {
            log.error("💥 CRASH: {}", e.getMessage());
            return "💥 IllegalStateException: " + e.getMessage()
                + " — Stream was consumed by count(), cannot reuse!";
        }
    }
}
