// ✅ FIX: Supplier<Stream<T>> creates fresh stream each time
package com.bank.report.service;

import com.bank.report.dto.TradeReport;
import com.bank.report.model.Trade;
import com.bank.report.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.Comparator;
import java.util.Map;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import java.util.stream.Stream;

@Service
@RequiredArgsConstructor
@Slf4j
public class SupplierReportService {

    private final TradeRepository tradeRepo;

    @Transactional(readOnly = true)
    public TradeReport generateReport() {
        // Load data ONCE from DB:
        var allTrades = tradeRepo.findAll();

        // Store the RECIPE (Supplier), not the stream:
        Supplier<Stream<Trade>> settledStream =
            () -> allTrades.stream().filter(Trade::isSettled);

        // Each .get() creates a BRAND NEW stream pipeline:

        // Stat 1: count (fresh stream #1)
        long totalCount = settledStream.get().count();
        log.info("[Supplier] Stream #1 → count: {}", totalCount);

        // Stat 2: sum (fresh stream #2)
        BigDecimal totalAmount = settledStream.get()
            .map(Trade::getAmount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        log.info("[Supplier] Stream #2 → total: Rs.{}", totalAmount);

        // Stat 3: max (fresh stream #3)
        BigDecimal largestTrade = settledStream.get()
            .map(Trade::getAmount)
            .max(Comparator.naturalOrder())
            .orElse(BigDecimal.ZERO);
        log.info("[Supplier] Stream #3 → largest: Rs.{}", largestTrade);

        // Stat 4: group by symbol (fresh stream #4)
        Map<String, Long> countBySymbol = settledStream.get()
            .collect(Collectors.groupingBy(Trade::getSymbol, Collectors.counting()));
        log.info("[Supplier] Stream #4 → by symbol: {}", countBySymbol);

        // Stat 5: CSV (fresh stream #5)
        String symbolsCsv = settledStream.get()
            .map(Trade::getSymbol)
            .distinct()
            .sorted()
            .collect(Collectors.joining(", "));
        log.info("[Supplier] Stream #5 → CSV: {}", symbolsCsv);

        return new TradeReport("Supplier<Stream<T>>",
            totalCount, totalAmount, largestTrade, countBySymbol, symbolsCsv,
            "5 fresh streams from Supplier.get() — no IllegalStateException!");
    }
}
