// ✅ ALTERNATIVE FIX: Collect to List first, reuse the List
package com.bank.report.service;

import com.bank.report.dto.TradeReport;
import com.bank.report.model.Trade;
import com.bank.report.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@Slf4j
public class CollectFirstReportService {

    private final TradeRepository tradeRepo;

    @Transactional(readOnly = true)
    public TradeReport generateReport() {
        // Materialize the filtered data ONCE into a List:
        List<Trade> settledList = tradeRepo.findAll().stream()
            .filter(Trade::isSettled)
            .toList();  // ONE stream, consumed here

        // Now reuse the LIST (not the stream) to create new streams:
        long totalCount = settledList.size();  // no stream needed!

        BigDecimal totalAmount = settledList.stream()
            .map(Trade::getAmount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        BigDecimal largestTrade = settledList.stream()
            .map(Trade::getAmount)
            .max(Comparator.naturalOrder())
            .orElse(BigDecimal.ZERO);

        Map<String, Long> countBySymbol = settledList.stream()
            .collect(Collectors.groupingBy(Trade::getSymbol, Collectors.counting()));

        String symbolsCsv = settledList.stream()
            .map(Trade::getSymbol)
            .distinct().sorted()
            .collect(Collectors.joining(", "));

        log.info("[Collect-first] All 5 stats from materialized List of {} trades", settledList.size());

        return new TradeReport("Collect-to-List-first",
            totalCount, totalAmount, largestTrade, countBySymbol, symbolsCsv,
            "Materialized once, reused List. For count: settledList.size() — no stream needed!");
    }
}
