// ─── File: src/test/java/com/bank/report/service/StreamReuseTest.java ───
package com.bank.report.service;

import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.function.Supplier;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.*;

class StreamReuseTest {

    // ═══ Stream cannot be reused — proves IllegalStateException ═══
    @Test
    void streamThrowsAfterTerminal() {
        Stream<String> stream = Stream.of("RELIANCE", "TCS", "HDFC");
        stream.count();  // terminal → consumed

        assertThatThrownBy(() -> stream.toList())
            .isInstanceOf(IllegalStateException.class)
            .hasMessageContaining("stream has already been operated upon or closed");
    }

    @Test
    void evenIntermediateFailsAfterTerminal() {
        Stream<String> stream = Stream.of("RELIANCE", "TCS");
        stream.count();

        assertThatThrownBy(() -> stream.filter(s -> true))
            .isInstanceOf(IllegalStateException.class);
    }

    // ═══ Supplier<Stream> workaround ═══
    @Test
    void supplierCreatesIndependentStreams() {
        Supplier<Stream<String>> factory = () -> Stream.of("RELIANCE", "TCS", "HDFC");

        long count = factory.get().count();            // stream #1
        List<String> list = factory.get().toList();    // stream #2
        String first = factory.get().findFirst().orElse("");  // stream #3

        assertThat(count).isEqualTo(3);
        assertThat(list).hasSize(3);
        assertThat(first).isEqualTo("RELIANCE");
    }

    @Test
    void supplierWithFilterPreservesRecipe() {
        List<String> source = List.of("RELIANCE", "TCS", "HDFC", "WIPRO");
        Supplier<Stream<String>> longNames = () -> source.stream()
            .filter(s -> s.length() > 4);

        assertThat(longNames.get().count()).isEqualTo(2);  // RELIANCE, WIPRO
        assertThat(longNames.get().toList()).containsExactly("RELIANCE", "WIPRO");
        // Both calls work — each .get() creates a fresh pipeline
    }

    // ═══ Collect-first alternative ═══
    @Test
    void collectFirstThenReuseList() {
        List<String> materialized = Stream.of("RELIANCE", "TCS", "HDFC")
            .filter(s -> s.length() > 3)
            .toList();  // materialize once

        // Reuse the LIST:
        long count = materialized.size();  // no stream needed
        String first = materialized.stream().findFirst().orElse("");
        String csv = String.join(", ", materialized);

        assertThat(count).isEqualTo(2);
        assertThat(first).isEqualTo("RELIANCE");
        assertThat(csv).isEqualTo("RELIANCE, HDFC");
    }

    // ═══ Supplier is lazy — pipeline built only on .get() ═══
    @Test
    void supplierIsLazy() {
        List<String> source = new java.util.ArrayList<>(List.of("A", "B"));
        Supplier<Stream<String>> factory = () -> source.stream();

        assertThat(factory.get().count()).isEqualTo(2);

        source.add("C");  // modify source AFTER creating Supplier

        // Next .get() sees the UPDATED source!
        assertThat(factory.get().count()).isEqualTo(3);
        // This is the key difference from collect-first:
        // Supplier reflects source changes. Collect-first is a snapshot.
    }
}
